window.ATLAS.addDetails("life.nodes",{"nodes":{
"blood-circulation":{"description":{"zh":"血液走体循环与肺循环两个环路，由心脏的瓣膜和四个腔保证单向流动；同一流量下总横截面积越大流速越小，平均动脉压约等于心输出量乘外周阻力。仅为教学示意与近似数值，不用于医疗判断。","en":"Blood travels a systemic and a pulmonary loop, kept one-way by the heart’s four chambers and valves; at the same flow a larger total cross-section means slower speed, and mean arterial pressure is roughly cardiac output times peripheral resistance. A teaching sketch with approximate numbers, not for medical judgement."},"formula":"MAP ≈ CO × R","source":"../biology/body/blood-circulation/#step1","lessons":[{"slug":"blood-circulation","step":1,"category":"biology","stage":"junior","primary":true}],"note":"No biology group exists in the atlas, so group is left OTHER for the coordinator. No existing atlas node fits as an endpoint, so the edge uses this page's own conceptId on both sides with a same-page reason.","aliases":{"zh":["心脏","心脏是怎么跳动的","心脏跳动","心脏是怎么工作的"],"en":["heart","how does the heart work","how does the heart pump"]}},
"cell-structure":{"description":{"zh":"细胞是生命的最小单位间：一层膜划出内外，细胞核指挥，线粒体供能，叶绿体（植物）光合，液泡储物。植物细胞比动物细胞多一面墙（细胞壁）和一个大水囊。","en":"The cell is life's smallest workshop: a membrane draws inside from outside, the nucleus commands, mitochondria supply energy, chloroplasts (plants) photosynthesize, vacuoles store. Plant cells add a wall and a large water sac over animal cells."},"source":"../biology/cells/cell-structure/#step1","lessons":[{"slug":"cell-structure","step":1,"category":"biology","stage":"junior","primary":true}],"aliases":{"zh":["细胞里有什么","细胞器"],"en":["organelles","what is inside a cell"]}},
"food-web":{"description":{"zh":"食物网用箭头画出能量从生产者逐级传给消费者的路径，每级约剩十分之一；移走一个物种的影响沿网传开，食物来源越多越稳；难降解毒物逐级放大。仅为虚构 8 种生物的教学模型。","en":"A food web uses arrows to show energy passed from producers up through consumers, about a tenth surviving each step; removing a species spreads along the web, more food sources make it sturdier, and persistent poisons magnify level by level. A teaching model of eight fictional organisms."},"formula":"E_n = E_1 · η^(n−1)","source":"../biology/ecology/food-web/#step1","lessons":[{"slug":"food-web","step":1,"category":"biology","stage":"junior","primary":true}],"note":"No biology group in the atlas; group left OTHER. No existing atlas node fits as an endpoint, so the edge uses this page's own conceptId on both sides with a same-page reason.","aliases":{"zh":["食物链","食物链是什么"],"en":["food chain","food chains"]}},
"photosynthesis":{"description":{"zh":"阳光供能，把水和二氧化碳拼成糖、放出氧气：一笔原子账，进来 6 个 CO₂ 加 6 个水，出去 1 个葡萄糖加 6 个氧气。光越强开工越快但有上限，二氧化碳不够时光再强也白搭。","en":"Sunlight powers assembling water and carbon dioxide into sugar and releasing oxygen — an atom ledger: 6 CO₂ plus 6 waters in, 1 glucose plus 6 oxygens out. Stronger light speeds work up to a ceiling, and when CO₂ runs short extra light is wasted."},"formula":"6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂","source":"../biology/cells/photosynthesis/#step1","lessons":[{"slug":"photosynthesis","step":1,"category":"biology","stage":"junior","primary":true}]},
"action-potential":{"description":{"zh":"刺激把膜电位推过阈值，Na⁺ 通道成片打开、Na⁺ 涌入让电位冲到正值，随后 Na⁺ 通道失活、K⁺ 外流又把它拉回来甚至略低于静息；刺激再强，尖峰也不会更高，只会发得更频繁，而不应期给频率设了上限。","en":"Once a stimulus pushes the membrane past threshold, Na⁺ channels open en masse and the inrush drives the voltage positive; then Na⁺ channels inactivate and K⁺ flows out, pulling it back, even slightly below rest; a stronger stimulus does not make a taller spike, only more frequent ones, and the refractory period caps the rate."},"source":"../biology/body/action-potential/#step1","lessons":[{"slug":"action-potential","step":1,"category":"biology","stage":"senior","primary":true},{"slug":"neuroscience-basics","step":1,"category":"biology","stage":"senior","primary":false}],"aliases":{"zh":["动作电位","神经冲动","全或无","阈电位","去极化 复极化","不应期","神经元怎么放电","刺激越强尖峰越高吗","神经怎么传信号","神经信号","神经元传递信号","神经元是怎么传递信号的"],"en":["action potential","nerve impulse","all-or-none","threshold potential","depolarisation and repolarisation","refractory period","how a neuron fires","does a stronger stimulus give a bigger spike","how do nerves send signals","nerve signal","how do neurons send signals"]}},
"epidemic-r0":{"description":{"zh":"R₀ 是一个病例在没人免疫、没有干预时平均传给几个人：大于 1，开头病例一代比一代多；但病人康复后免疫，易感者越来越少，降到总人口的 1/Rₑ 时曲线掉头，这就是群体免疫阈值。干预把有效再生数 Rₑ 压低，峰值变低变晚，但变平不等于消失。","en":"R₀ is how many people one case infects on average when nobody is immune and nothing is done: above 1, cases multiply each generation at first; but recovered people are immune, susceptibles run down, and when they fall to 1/Rₑ of the population the curve turns — the herd-immunity threshold. Interventions push the effective number Rₑ down, so the peak is lower and later — but flatter is not the same as gone."},"formula":"Rₑ = R₀·(1 − intervention)","source":"../biology/body/public-health/#step0","lessons":[{"slug":"public-health","step":0,"category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["基本传染数","R0 是什么意思","有效再生数 Rt","压平曲线","传染病怎么传播","流行病学","公共卫生","群体免疫","疫情峰值","SIR模型","SIR","传染病模型","传染病是怎么传播的"],"en":["basic reproduction number","what does R0 mean","effective reproduction number","flatten the curve","how epidemics spread","epidemiology","public health","herd immunity","epidemic peak","SIR model","epidemic model","how do diseases spread"]}},
"logistic-growth":{"description":{"zh":"没有天花板时种群按比例越长越快（指数增长）；环境最多养得起 K 个，于是实际增长率变成 r·(1 − N/K)，越接近 K 涨得越慢，曲线被压成 S 形，从上方超载也会回落到 K。","en":"With no ceiling a population grows in proportion to its size — ever faster (exponential growth); the environment can support at most K, so the actual rate becomes r·(1 − N/K), slowing as N nears K and bending the curve into an S; a population that starts above K falls back to it."},"formula":"N ← N + rN(1 − N/K)","source":"../biology/ecology/logistic-growth/#step2","lessons":[{"slug":"logistic-growth","step":2,"category":"biology","stage":"senior","primary":true},{"slug":"population-ecology","step":1,"category":"biology","stage":"senior","primary":false}],"aliases":{"zh":["S 形曲线","逻辑斯蒂模型","环境容纳量 K","种群增长","J 形增长和 S 形增长","种群为什么不会无限增长","logistic 增长"],"en":["S-curve","logistic model","carrying capacity","population growth","J-shaped vs S-shaped growth","why populations stop growing","logistic function"]}},
"membrane-transport":{"description":{"zh":"分子在膜两侧随机来回穿越，浓度高的一侧穿过来的更多，于是出现顺着浓度差的净流动（扩散）；水跟着溶质浓度走（渗透），细胞随之胀大或皱缩；想逆着浓度差搬运，就要消耗 ATP 让泵来做。","en":"Molecules cross a membrane at random in both directions, but more come from the crowded side, giving a net flow down the concentration difference (diffusion); water follows the solute concentration (osmosis), swelling or shrinking the cell; moving things against the difference takes ATP-powered pumps."},"source":"../biology/cells/membrane-transport/","lessons":[{"slug":"membrane-transport","step":null,"category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["物质跨膜运输","自由扩散","渗透作用","主动运输","被动运输","钠钾泵","高渗 低渗 等渗","红细胞放进清水会怎样","细胞膜的选择透过性"],"en":["transport across the cell membrane","simple diffusion","osmosis","active transport","passive transport","sodium–potassium pump","hypertonic hypotonic isotonic","what happens to a red blood cell in pure water","selective permeability"]}},
"predator-prey":{"description":{"zh":"猎物多时捕食者吃得饱、数量上升，捕食者多了又把猎物吃少，随后自己也饿下去——两个种群互相牵制，又各慢一拍，于是数量此起彼伏，捕食者的峰总落在猎物的峰之后。","en":"When prey are plentiful predators thrive and multiply, more predators then eat the prey down, and later starve themselves — each population holds the other in check with a lag, so their numbers rise and fall in turn, the predator peak always trailing the prey peak."},"source":"../biology/ecology/population-ecology/#step2","lessons":[{"slug":"population-ecology","step":2,"category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["捕食者猎物模型","Lotka–Volterra 方程","狼和兔子的数量","种群波动","猞猁和雪兔","为什么捕食者的峰比猎物晚","种群生态学","捕食者和猎物数量变化","捕食者与猎物"],"en":["predator–prey model","Lotka–Volterra equations","wolves and rabbits populations","population cycles","lynx and hare","why predator peaks lag prey peaks","population ecology","predator and prey","predator prey"]}},
"resting-potential":{"description":{"zh":"神经元不放电时膜内比膜外低约 70 毫伏：K⁺ 容易从漏通道流出、把膜内拉负，少量 Na⁺ 漏入又把它往上拉，两者平衡的位置就是静息电位，它是每一次神经信号的起点。","en":"A neuron at rest sits about 70 millivolts more negative inside than outside: K⁺ leaking out through its channels pulls the inside negative, a little Na⁺ leaking in pulls it back up, and the balance point is the resting potential — the starting line for every nerve signal."},"formula":"≈ −70 mV","source":"../biology/body/neuroscience-basics/#step0","lessons":[{"slug":"neuroscience-basics","step":0,"category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["静息电位","膜电位","−70 mV","神经元为什么带电","钾离子漏通道","神经科学入门"],"en":["resting potential","membrane potential","minus 70 millivolts","why neurons are electrically charged","potassium leak channels","neuroscience basics"]}},
"steady-state-set-point":{"description":{"zh":"流出量跟存量成正比时，存量会自己停在“进水 ÷ 漏的比例”处，被推开后差距按固定时间减半。","en":"When outflow is proportional to the stock, the stock settles at inflow ÷ leak rate and any push decays by half in a fixed time."},"source":"../biology/body/body-in-balance/#ch1","lessons":[{"slug":"body-in-balance","step":null,"anchor":"ch1","category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["稳态","内环境稳态","一级动力学","为什么身体能保持平衡","漏水的桶"],"en":["homeostasis","steady state","first-order kinetics","leaky bucket","why does the body stay balanced"]}},
"working-memory-attention":{"description":{"zh":"大脑能同时抓住的东西很有限：工作记忆一次只维持几个单元，把项目分组能腾出空间；注意像带宽有限的通道，干扰越多越难找到目标；记忆痕迹随时间变弱，新旧内容还会互相干扰，而一个好的提取线索能把它拉回来。","en":"The mind can hold only a little at once: working memory keeps a handful of units in play, and grouping items frees up room; attention is a channel of limited bandwidth, so more distractors make targets harder to find; memory traces fade with time and old and new material interfere, while a good retrieval cue can bring them back."},"source":"../psychology/cognition/memory-attention/#step0","lessons":[{"slug":"memory-attention","step":0,"category":"psychology","stage":"senior","primary":true}],"aliases":{"zh":["工作记忆","短时记忆容量","神奇的数字 7±2","组块","遗忘曲线","前摄干扰 后摄干扰","为什么记不住","注意力不集中"],"en":["working memory","short-term memory capacity","magical number seven","chunking","forgetting curve","proactive and retroactive interference","why can’t I remember","trouble paying attention"]}},
"drug-half-life-plateau":{"description":{"zh":"按时服药，体内药量约五个半衰期后到平台；漏服与补双倍各有什么后果。","en":"Regular doses climb to a plateau in about five half-lives; what a missed dose or a double dose does."},"source":"../biology/body/body-in-balance/#ch2","lessons":[{"slug":"body-in-balance","step":null,"anchor":"ch2","category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["半衰期","药物半衰期","为什么每8小时吃一次药","漏服了要不要补","稳态血药浓度","药为什么要吃几天才见效","按时吃药","吃药为什么要按时","药在体内能留多久","药物代谢"],"en":["half-life","drug half-life","steady state concentration","why take every 8 hours","missed dose double up","why does medicine take days to work","take medicine at regular times","how long do drugs stay in your body","drug metabolism"]}},
"alcohol-zero-order":{"description":{"zh":"分解酒精的酶很快饱和，每小时只能清除差不多固定的量，所以下降是直线、喝得太快就没有平台。","en":"The enzyme that breaks down alcohol saturates early, so a roughly fixed amount leaves per hour: a straight-line fall and no plateau if you drink faster."},"source":"../biology/body/body-in-balance/#ch3","lessons":[{"slug":"body-in-balance","step":null,"anchor":"ch3","category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["零级动力学","酒精代谢","醒酒要多久","血液酒精浓度","为什么酒精是直线下降","喝酒多久能醒","醒酒"],"en":["zero-order kinetics","alcohol metabolism","how long to sober up","blood alcohol concentration","Michaelis-Menten elimination","how fast alcohol leaves the body"]}},
"glucose-feedback":{"description":{"zh":"胰岛素和胰高血糖素把血糖往回推；反应太弱会偏高很久，太晚又太猛会跌过头。","en":"Insulin and glucagon push glucose back; a weak response leaves it high, a late and strong one overshoots into a dip."},"source":"../biology/body/body-in-balance/#ch4","lessons":[{"slug":"body-in-balance","step":null,"anchor":"ch4","category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["负反馈","胰岛素","胰高血糖素","饭后血糖","低血糖为什么会发生","糖尿病血糖为什么降不下来","吃完饭血糖"],"en":["negative feedback","insulin","glucagon","blood sugar after a meal","reactive hypoglycemia","why diabetes keeps glucose high"]}},
"fever-set-point":{"description":{"zh":"致热原把体温设定点拨高，所以发烧时发冷、退烧时出汗；中暑的高热则是散热到了上限。","en":"Pyrogens raise the temperature set point, so a fever starts with chills and breaks with sweating; heat stroke is cooling at its limit instead."},"source":"../biology/body/body-in-balance/#ch5","lessons":[{"slug":"body-in-balance","step":null,"anchor":"ch5","category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["发烧","体温调节","为什么发烧会发冷","退烧为什么出汗","中暑和发烧的区别","体温设定点"],"en":["fever","thermoregulation","why do you feel cold with a fever","sweating when a fever breaks","heat stroke vs fever","temperature set point"]}},
"therapeutic-window":{"description":{"zh":"有效浓度和有害浓度之间的距离；同样的总量分几次吃、清除变慢，会让体内的量落在窗里还是窗外。","en":"The gap between an effective and a harmful level; how splitting the same daily dose, or slower clearance, keeps the level inside or outside it."},"source":"../biology/body/body-in-balance/#ch6","lessons":[{"slug":"body-in-balance","step":null,"anchor":"ch6","category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["治疗窗","治疗指数","剂量反应曲线","药物过量","为什么肾功能差要减量"],"en":["therapeutic window","therapeutic index","dose-response curve","overdose","why reduce dose for kidney impairment"]}},
"cardiac-output-budget":{"description":{"zh":"运动时身体守住的是供氧，心率和每搏量被调动；锻炼降低静息心率，年龄压低心率上限。","en":"During exercise the body holds oxygen delivery and moves heart rate and stroke volume; training lowers resting heart rate, age lowers the maximum."},"source":"../biology/body/body-in-balance/#ch7","lessons":[{"slug":"body-in-balance","step":null,"anchor":"ch7","category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["心输出量","每搏量","最大心率","为什么运动员心率低","运动时心跳为什么加快"],"en":["cardiac output","stroke volume","maximum heart rate","why athletes have low heart rates","why heart rate rises in exercise"]}},
"antibiotic-selection-window":{"description":{"zh":"浓度落在敏感菌和耐药菌的 MIC 之间时，药会替耐药菌清出地方；提前停药是否偏向耐药，取决于剂量。","en":"Concentrations between the sensitive and resistant MICs clear the way for resistant bacteria; whether stopping early favours resistance depends on the dose."},"source":"../biology/body/body-in-balance/#ch8","lessons":[{"slug":"body-in-balance","step":null,"anchor":"ch8","category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["抗生素耐药","突变选择窗","最低抑菌浓度","抗生素要吃完吗","为什么细菌会耐药"],"en":["antibiotic resistance","mutant selection window","minimum inhibitory concentration","do you need to finish antibiotics","why bacteria become resistant","finish the course of antibiotics"]}},
"herd-immunity-threshold":{"description":{"zh":"免疫比例超过 1 − 1/R₀ 时，每个病例平均传给不到一个人，疫情自己熄灭。","en":"Once the immune share exceeds 1 − 1/R₀, each case infects fewer than one other on average and the outbreak dies out."},"source":"../biology/body/body-in-balance/#ch9","lessons":[{"slug":"body-in-balance","step":null,"anchor":"ch9","category":"biology","stage":"senior","primary":true}],"aliases":{"zh":["群体免疫","疫苗接种率要多少","麻疹疫苗覆盖率","有效再生数","打疫苗","为什么要打疫苗"],"en":["herd immunity","vaccination coverage needed","measles vaccination threshold","effective reproduction number","vaccines","vaccination","how many people need to be vaccinated"]}}
}});
